package com.kampotourism.itinerary;
import com.kampotourism.common.*; import com.kampotourism.common.error.*; import com.kampotourism.common.i18n.LanguageResolver; import com.kampotourism.content.*; import com.kampotourism.itinerary.ItineraryDtos.*; import com.kampotourism.media.*; import com.kampotourism.media.MediaDtos.OwnerImages; import java.util.*; import java.util.stream.Collectors; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class ItineraryService {
 private final ItineraryRepository items; private final ItineraryTranslationRepository texts; private final ItineraryDayRepository days; private final ItineraryActivityRepository activities; private final ContentItemRepository content; private final DestinationRepositoryProxy destinations; private final MediaAttachmentService images; private final LanguageResolver languages;
 public ItineraryService(ItineraryRepository items,ItineraryTranslationRepository texts,ItineraryDayRepository days,ItineraryActivityRepository activities,ContentItemRepository content,com.kampotourism.destination.DestinationRepository destinationRepository,MediaAttachmentService images,LanguageResolver languages){this.items=items;this.texts=texts;this.days=days;this.activities=activities;this.content=content;this.destinations=new DestinationRepositoryProxy(destinationRepository);this.images=images;this.languages=languages;}
 @Transactional(readOnly=true) public PageResponse<Card> list(Boolean featured,int page,int size,String lang){int p=Math.max(1,page),s=Math.min(50,Math.max(1,size));Pageable pageable=PageRequest.of(p-1,s,Sort.by("sortOrder","id"));org.springframework.data.domain.Page<Itinerary> result=featured==null?items.findByStatus(ContentStatus.PUBLISHED,pageable):items.findByStatusAndFeatured(ContentStatus.PUBLISHED,featured,pageable);List<Itinerary> slice=result.getContent();Map<Long,ItineraryTranslation> t=pick(slice,lang);Map<Long,OwnerImages> m=images.publicImages(OwnerType.ITINERARY,slice.stream().map(Itinerary::getId).toList(),lang);return new PageResponse<>(slice.stream().filter(i->t.containsKey(i.getId())).map(i->new Card(i.getSlug(),t.get(i.getId()).getTitle(),i.getDaysCount(),i.isFeatured(),m.getOrDefault(i.getId(),new OwnerImages(null,List.of())).cover(),t.get(i.getId()).getLang())).toList(),p,s,result.getTotalElements(),result.getTotalPages());}
 @Transactional(readOnly=true) public Detail get(String slug,String lang){Itinerary i=items.findBySlugAndStatus(slug,ContentStatus.PUBLISHED).orElseThrow(()->new NotFoundException("Itinerary '"+slug+"' was not found")); ItineraryTranslation t=pick(List.of(i),lang).get(i.getId()); if(t==null)throw new NotFoundException("Itinerary '"+slug+"' was not found"); OwnerImages m=images.publicImages(OwnerType.ITINERARY,List.of(i.getId()),lang).getOrDefault(i.getId(),new OwnerImages(null,List.of()));return new Detail(i.getSlug(),t.getTitle(),t.getDescription(),i.getDaysCount(),m.cover(),m.gallery(),activityDays(i.getId()),t.getLang());}
 public AdminDetail create(CreateRequest r){if(items.existsBySlug(r.slug()))throw new ConflictException("Slug is already in use"); Itinerary i=items.saveAndFlush(new Itinerary(r.slug(),r.featured(),r.sortOrder(),r.days().size())); saveText(i.getId(),languages.defaultLang(),r.translation()); replaceDays(i.getId(),r.days());return detail(i);}
 public AdminDetail update(long id,UpdateRequest r){Itinerary i=find(id);if(i.getVersion()!=r.version())throw new ConflictException("This itinerary was changed by someone else. Reload it and try again.");if(items.existsBySlugAndIdNot(r.slug(),id))throw new ConflictException("Slug is already in use");i.edit(r.slug(),r.featured(),r.sortOrder(),r.daysCount());items.saveAndFlush(i);return detail(i);}
 public AdminDetail setDays(long id,List<DayBody> value){Itinerary i=find(id);if(value==null||value.isEmpty()||value.size()>60)throw new BadRequestException("An itinerary must have between 1 and 60 days"); i.edit(i.getSlug(),i.isFeatured(),i.getSortOrder(),value.size());replaceDays(id,value);if(i.getStatus()==ContentStatus.PUBLISHED)validateReferences(i.getId());return detail(i);}
 public AdminDetail text(long id,String lang,TranslationBody b){find(id);saveText(id,languages.requireSupported(lang),b);return detail(find(id));}
 public void deleteText(long id,String lang){find(id);String l=languages.requireSupported(lang);if(l.equals(languages.defaultLang()))throw new ConflictException("The default-language translation cannot be removed.");texts.deleteByItineraryIdAndLang(id,l);}
 public AdminDetail status(long id,ContentStatus status){Itinerary i=find(id);if(status==ContentStatus.PUBLISHED)validateReferences(i.getId());i.status(status);items.saveAndFlush(i);return detail(i);}
 public AdminDetail images(long id,ImagesRequest r){find(id);images.replace(OwnerType.ITINERARY,id,r.cover(),r.gallery());return detail(find(id));}
 public void delete(long id){Itinerary i=find(id);if(i.getStatus()==ContentStatus.PUBLISHED)throw new ConflictException("Unpublish before deleting; archive is preferred.");images.deleteAllFor(OwnerType.ITINERARY,id);items.delete(i);}
 @Transactional(readOnly=true) public PageResponse<AdminDetail> adminList(String status,int page,int size){ContentStatus s=status==null||status.equalsIgnoreCase("all")?null:parse(status);int p=Math.max(1,page),z=Math.min(100,Math.max(1,size));Pageable pageable=PageRequest.of(p-1,z,Sort.by(Sort.Order.desc("updatedAt"),Sort.Order.desc("id")));org.springframework.data.domain.Page<Itinerary> result=s==null?items.findAll(pageable):items.findByStatus(s,pageable);return new PageResponse<>(result.getContent().stream().map(this::detail).toList(),p,z,result.getTotalElements(),result.getTotalPages());}
 @Transactional(readOnly=true) public AdminDetail adminGet(long id){return detail(find(id));}
 private void replaceDays(long itineraryId,List<DayBody> value){List<ItineraryDay> old=days.findByItineraryIdOrderByDayNumberAsc(itineraryId);if(!old.isEmpty())activities.deleteByDayIdIn(old.stream().map(ItineraryDay::getId).toList());days.deleteByItineraryId(itineraryId);for(int n=0;n<value.size();n++){ItineraryDay d=days.save(new ItineraryDay(itineraryId,n+1));int order=0;for(ActivityBody a:value.get(n).activities()){validateActivity(a);activities.save(new ItineraryActivity(d.getId(),order++,a.destinationId(),a.experienceId()));}}}
 private void validateActivity(ActivityBody a){if(a==null||((a.destinationId()==null)==(a.experienceId()==null)))throw new BadRequestException("Each activity must reference exactly one destination or experience");if(a.destinationId()!=null&&!destinations.exists(a.destinationId()))throw new BadRequestException("Unknown destination "+a.destinationId());if(a.experienceId()!=null){ContentItem x=content.findById(a.experienceId()).orElseThrow(()->new BadRequestException("Unknown experience "+a.experienceId()));if(x.getType()!=ContentType.EXPERIENCE)throw new BadRequestException("Activity references must be experiences");}}
 private void validateReferences(long id){for(Day d:activityDays(id))for(Activity a:d.activities()){if(a.targetType().equals("destination")&&!destinations.published(a.targetId()))throw new BadRequestException("Itinerary references an unpublished destination");if(a.targetType().equals("experience")){ContentItem x=content.findById(a.targetId()).orElseThrow(()->new BadRequestException("Itinerary has a missing experience"));if(x.getStatus()!=ContentStatus.PUBLISHED)throw new BadRequestException("Itinerary references an unpublished experience");}}}
 private List<Day> activityDays(long id){List<ItineraryDay> ds=days.findByItineraryIdOrderByDayNumberAsc(id);Map<Long,List<ItineraryActivity>> by=ds.isEmpty()?Map.of():activities.findByDayIdInOrderBySortOrderAscIdAsc(ds.stream().map(ItineraryDay::getId).toList()).stream().collect(Collectors.groupingBy(ItineraryActivity::getDayId));return ds.stream().map(d->new Day(d.getDayNumber(),by.getOrDefault(d.getId(),List.of()).stream().map(a->a.getDestinationId()!=null?new Activity(a.getId(),a.getSortOrder(),"destination",a.getDestinationId()):new Activity(a.getId(),a.getSortOrder(),"experience",a.getExperienceId())).toList())).toList();}
 private void saveText(Long id,String lang,TranslationBody b){ItineraryTranslation t=texts.findByItineraryIdAndLang(id,lang).orElseGet(()->new ItineraryTranslation(id,lang));t.edit(b.title(),b.description(),b.seoTitle(),b.seoDescription());texts.save(t);} private Map<Long,ItineraryTranslation> pick(Collection<Itinerary> list,String lang){if(list.isEmpty())return Map.of();Map<Long,ItineraryTranslation> out=new HashMap<>();for(ItineraryTranslation t:texts.findByItineraryIdInAndLangIn(list.stream().map(Itinerary::getId).toList(),Set.copyOf(List.of(lang,languages.defaultLang()))))if(t.getLang().equals(lang)||!out.containsKey(t.getItineraryId()))out.put(t.getItineraryId(),t);return out;}
 private Itinerary find(long id){return items.findById(id).orElseThrow(()->new NotFoundException("Itinerary "+id+" was not found"));} private ContentStatus parse(String s){try{return ContentStatus.valueOf(s.toUpperCase());}catch(Exception e){throw new BadRequestException("status must be all, draft, published, or archived");}} private AdminDetail detail(Itinerary i){Map<String,TranslationBody> all=new TreeMap<>();texts.findByItineraryId(i.getId()).forEach(t->all.put(t.getLang(),new TranslationBody(t.getTitle(),t.getDescription(),t.getSeoTitle(),t.getSeoDescription())));return new AdminDetail(i.getId(),i.getVersion(),i.getSlug(),i.getStatus(),i.isFeatured(),i.getSortOrder(),i.getDaysCount(),i.getPublishedAt(),i.getUpdatedAt(),images.adminImages(OwnerType.ITINERARY,i.getId()),all,activityDays(i.getId()));}
 private record DestinationRepositoryProxy(com.kampotourism.destination.DestinationRepository repo){boolean exists(long id){return repo.existsById(id);} boolean published(long id){return repo.findById(id).map(com.kampotourism.destination.Destination::isPublished).orElse(false);}}
}
